package com.bettercontent.betterwildfruittrees.gametest.queueproof;
import java.nio.file.*;import java.util.*;import java.security.*;
public final class PreparationAuditSelfTest {
 static String hash(Path p)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(p)));}
 static Properties binding(Path root)throws Exception{Files.createDirectories(root);Properties p=new Properties();p.setProperty("nonce",root.getFileName().toString());p.setProperty("attemptDirectory",root.toString());p.setProperty("profile","light-queue-proof-v1-required29");p.setProperty("sourceDirty","false");p.setProperty("sourceCommit","a".repeat(40));for(String[] pair:new String[][]{{"classHashSetSha256","light-queue-proof-classes.sha256"},{"nativeInputReceiptSha256","before-own-prepare.properties"}}){Path input=root.resolve(pair[1]);Files.writeString(input,"authored inert control, NOT native evidence");p.setProperty(pair[0],hash(input));}return p;}
 public static void main(String[] args)throws Exception{Path parent=Path.of(args[0]).toAbsolutePath();Files.createDirectories(parent);for(String mode:new String[]{"good","nonce","source","dirty","hash","existing","symlink","overflow"}){Path root=parent.resolve(UUID.randomUUID().toString());Properties p=binding(root);if(mode.equals("nonce"))p.setProperty("nonce","wrong");if(mode.equals("source"))p.remove("sourceCommit");if(mode.equals("dirty"))p.setProperty("sourceDirty","true");if(mode.equals("hash"))Files.writeString(root.resolve("before-own-prepare.properties"),"tamper");if(mode.equals("existing"))Files.writeString(root.resolve("light-queue-proof-preparation.properties"),"retain");if(mode.equals("symlink")){Path link=parent.resolve("link");Files.createSymbolicLink(link,root);root=link;p.setProperty("nonce","link");p.setProperty("attemptDirectory",link.toString());}if(mode.equals("overflow"))for(int i=0;i<1030;i++)PreparationAudit.record("metadata="+i);boolean fail=false;try{PreparationAudit.write(root,p);}catch(Exception expected){fail=true;}boolean valid=mode.equals("good")||mode.equals("overflow");if(fail==valid)throw new AssertionError(mode);if(mode.equals("existing")&&!Files.readString(root.resolve("light-queue-proof-preparation.properties")).equals("retain"))throw new AssertionError("overwritten");if(mode.equals("overflow")){Properties result=new Properties();try(var in=Files.newInputStream(root.resolve("light-queue-proof-preparation.properties"))){result.load(in);}if(!"true".equals(result.getProperty("incomplete"))||!"1024".equals(result.getProperty("rows")))throw new AssertionError("bound");}}
 var tiles=QueueClearPolicy.footprint(-16,-16,80,80);var state=new PreparationLeaseAudit(77,tiles);if(tiles.size()!=64||state.full!=-1L)throw new AssertionError("64 mask");state.entry(-16,-20,-16,80,0,80);state.before=1;state.beforeKnown=true;
 class Port implements QueueClearPolicy.Port {long forced=1;int failAt=-1;RuntimeException failure=new RuntimeException("admission");public boolean onThread(){return true;}public long now(){return 0;}public boolean forced(QueueClearPolicy.Tile tile){return (forced&state.bit(tile))!=0;}public void force(QueueClearPolicy.Tile tile,boolean value){long bit=state.bit(tile);if(value){state.attempted(tile);forced|=bit;if(tiles.indexOf(tile)==failAt)throw failure;}else forced&=~bit;}public void admit(){}public QueueClearPolicy.Stage snapshot(QueueClearPolicy.Tile tile){return new QueueClearPolicy.Stage(){public boolean done(){return true;}public void verify(){state.ready(PreparationLeaseAudit.key(tile));}};}public void pump(java.util.function.BooleanSupplier stop){if(!stop.getAsBoolean())throw new AssertionError();}}
 Port success=new Port();var lease=QueueClearPolicy.prepare(success,tiles);state.readyForced=success.forced;state.readyKnown=true;if(state.ready!=-1L||state.added!=-2L||state.readyForced!=-1L)throw new AssertionError("ready identity");lease.close();state.after=success.forced;state.afterKnown=true;if(state.after!=1)throw new AssertionError("lease identity not restored");state.row("CLOSED");state.added=0;Port failed=new Port();failed.failAt=2;try{QueueClearPolicy.prepare(failed,tiles);throw new AssertionError();}catch(RuntimeException actual){if(actual!=failed.failure)throw new AssertionError("original failure replaced",actual);}state.after=failed.forced;state.incomplete=true;state.row("PREPARE_FAILED_AFTER_POLICY_CLEANUP");if(state.added!=6||state.after!=1)throw new AssertionError("partial admission identity");
 System.out.println("PASS cold audit binding/missing/dirty/tamper/CREATE_NEW/symlink/bound negatives; metadata consistency is NOT native admission or authenticity");}
}
